	/**
	 * The character a name breaks its lines at, which is the content's own convention
	 * and not a path separator.
	 *
	 * NAMED ONCE because {@link #lines} walks the name twice - once to count the lines
	 * and once to cut them - and two loops that disagree about the character do not
	 * draw a wrong label, they walk off the end of the array they just sized.
	 */
	public static final char BREAK = '/';

	/**
	 * A name split at its breaks, which is how it is drawn: one line under the next.
	 *
	 * A name with no break in it comes back as one line, which is most of them.
	 */
	public static String[] lines(String name) {
		int parts = 1;
		for (int at = 0; at < name.length(); at++) {
			if (name.charAt(at) == BREAK) {
				parts++;
			}
		}
		String[] out = new String[parts];
		int from = 0;
		int which = 0;
		for (int at = 0; at <= name.length(); at++) {
			if (at == name.length() || name.charAt(at) == BREAK) {
				out[which++] = name.substring(from, at);
				from = at + 1;
			}
		}
		return out;
	}
